INSERT INTO `pages` VALUES (1,NULL,'home','page','Trang Chủ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'2026-08-02 16:46:01','2026-08-02 16:46:01',1,0,NULL,'root','3 Nông - Vật tư nông nghiệp','3nong, vat tu nong nghiep','Chuyên cung cấp vật tư nông nghiệp chất lượng cao'),(2,NULL,'gioi-thieu','page','Giới Thiệu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'2026-08-02 16:46:01','2026-08-04 11:21:25',1,0,'page','root','Giới Thiệu - 3 Nông','gioi thieu 3nong, ve 3nong','Giới thiệu về 3 Nông - Đơn vị cung cấp sản phẩm nông nghiệp uy tín'),(3,NULL,'dai-ly','page','Đại Lý',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'2026-08-02 16:46:01','2026-08-04 11:20:52',1,0,'page','root','Đăng Ký Đại Lý - 3 Nông','dai ly 3nong, dang ky dai ly','Hợp tác phát triển đại lý phân phối cùng 3 Nông'),(4,NULL,'lien-he','page','Liên Hệ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'2026-08-02 16:46:01','2026-08-04 11:21:14',1,0,'page','root','Liên Hệ - 3 Nông','lien he 3nong, tu van 3nong','Thông tin liên hệ và tư vấn hỗ trợ từ 3 Nông'),(5,NULL,'tin-tuc','page','Tin Tức',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'2026-08-02 16:46:01','2026-08-04 11:21:04',1,0,'page','root','Tin Tức & Kinh Nghiệm Nông Nghiệp - 3 Nông','tin tuc 3nong, kiem nghiem nong nghiep','Cập nhật tin tức và kiến thức kỹ thuật nông nghiệp'),(101,NULL,'tom-su-rim-hanh-toi','post','TÔM SÚ RIM HÀNH TỎI',NULL,'TÔM SÚ RIM HÀNH TỎI			',NULL,'<p>1. Nguyên liệu:\r\n</p><p>- 20 con tôm to (có thể dùng tôm sú hay tôm bạc)\r\n</p><p>- 2 tép tỏi to, 1 củ hành tím, 2 thìa canh dầu hạt điều để tạo màu đỏ, 2 thìa canh nước mắm ngon, 1 thìa canh đầy đường, chút dầu mè thơm, hạt tiêu.\r\n</p><p>2. Cách làm:\r\n</p><p>- Tôm bóc nõn, rút chỉ đen ở lưng rồi chà muối rửa sạch, lau khô, sau đó khía dọc lưng tôm. Tỏi và hành tím bóc vỏ, rửa sạch, băm nhỏ, chia làm 2 phần.\r\n</p><p>- Ướp tôm với một phần hành tỏi, nước mắm, đường, 1 thìa canh dầu hạt điều, ít hạt tiêu, chút dầu mè thơm khoảng 1 giờ cho thấm.\r\n</p><p>- Cho chảo lên bếp để lửa vừa, cho nốt thìa dầu điều vào đun nóng, cho phần hành tỏi vào phi thơm rồi cho tôm vào rán hai mặt cho tôm vừa chín tới. Tiếp theo cho hết phần nước ướp tôm vào rim cho đến khi tôm chín hẳn.\r\n</p><p>- Khi tôm chín thì tắt bếp, rắc thêm tiêu rồi cho ra đĩa, dùng với cơm trắng.</p><p>\r\n</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'upload/images/post/thumbnail/1650680778_808320.jpg',NULL,NULL,1,'2022-04-23 02:26:18','2026-04-11 13:04:57',1,0,NULL,'root','TÔM SÚ RIM HÀNH TỎI','','TÔM SÚ RIM HÀNH TỎI			'),(102,NULL,'tim-hieu-ve-ca-bop-bien-tuoi-song','post','Tìm Hiểu Về Cá Bớp Biển Tươi Sống',NULL,'Tìm Hiểu Về Cá Bớp Biển Tươi Sống',NULL,'<p>Cá Bóp Biển Tươi Sống\r\n</p><p>Toàn bộ cá bớp biển của chúng tôi là những con tốt nhất trên thị trường và có thịt ngọt, săn chắc kết hợp đẹp mắt với một loạt các thành phần.\r\n</p><p>Cá bớp biển là một loại cá trắng có thể được nấu theo cách giống như cá tráp đen anh em họ hoang dã của nó. Toàn bộ con cá là phù hợp nhất để nướng trong lò, mặc dù kích thước của nó có nghĩa là bạn cần một ấm đun nước cá nếu muốn luộc chín, vì bạn thường có thể đặt vừa hai con trong một chảo áp chảo rộng.</p><p><img src=\"http://localhost/3nong.vn/upload/post/20220423044454-649814.jpg\" style=\"width: 280px;\"></p><p>Mặc dù ngày càng phổ biến, cá bớp biển vẫn tương đối rẻ và do đó, là một loài cá tuyệt vời để thử nghiệm. Hương vị tinh tế của nó kết hợp với thì là, cây me chua, nước chanh, cỏ xạ hương, mùi tây, ngải giấm, mù tạt Anh, ô liu, măng tây, cà chua, hạnh nhân và đậu vườn. Nếu bạn tự trồng rau thì hãy thử dùng cá bớp biển nguyên con làm trung tâm của món ăn tôn vinh hương vị của mùa.\r\n</p><p>Theo nguyên tắc chung, một con cá tráp biển sẽ phục vụ một người như món chính và hai người là món khai vị:\r\n</p><p>Dinh dưỡng\r\n</p><p>Mỗi 100g cá tráp sống\r\n</p><p>Năng lượng 172kcal\r\n</p><p>Chất béo 11,1g (trong đó chất béo bão hòa 2,5g)\r\n</p><p>Chất đạm 16g</p><p>\r\n</p><p>\r\n</p><p>\r\n</p><p>\r\n</p><p>\r\n</p><p>\r\n</p><p>\r\n</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'upload/images/post/thumbnail/1650681894_607907.jpg',NULL,NULL,1,'2022-04-23 02:44:54','2026-07-07 19:36:42',1,0,NULL,'root','Tìm Hiểu Về Cá Bớp Biển Tươi Sống','','Tìm Hiểu Về Cá Bớp Biển Tươi Sống'),(1001,NULL,'chinh-sach-bao-hanh-doi-tra','page','Chính Sách Bảo Hành - Đổi Trả','Terms of service','					','Negotiate terms of this joint service (the \"Agreement\") is entered into by the parties to the SOC Co., Jsc. (abbreviated as SOC) and customers.','<p><b>Điều 1: Tổng quan</b></p><p><span style=\"font-size: 1rem;\">Thỏa thuận điều khoản dịch vụ chung này (\"Thỏa thuận\") được lập bởi các bên tham gia là Công Ty Cổ Phần SOC (Gọi tắt là SOC) và Quý khách, có hiệu lực từ ngày Quý khách sử dụng website này. Thỏa thuận này quy định các điều khoản và điều kiện chung về việc Quý khách sử dụng website cũng như các sản phẩm và dịch vụ được mua hay sử dụng thông qua website này, và bổ sung cho (không thay thế cho) bất cứ điều khoản và điều kiện nào được áp dụng cho các Dịch vụ cụ thể.</span></p><p>Cho dù Quý khách chỉ đơn giản là duyệt hay sử dụng website này hay mua các Dịch vụ, việc sử dụng website này và việc chấp nhận ở dạng điện tử Thỏa thuận này đồng nghĩa với việc Quý khách đã đọc, hiểu, xác nhận và đồng ý chịu sự ràng buộc bởi Thỏa thuận này cũng như các chính sách và các thỏa thuận về sản phẩm được áp dụng kèm theo được đưa vào với mục đích tham khảo trong tài liệu này.</p><p>Những đơn hàng đăng ký online sau khi SOC nhận chuyển khoản và tiến hành  khởi tạo dịch vụ, khách hàng cần phải bổ sung hợp đồng trong vòng 3 tháng kể từ ngày dịch vụ được khởi tạo. Nếu khách hàng không bổ sung hợp đồng thì SOC có quyền tạm khóa dịch vụ cho đến khi khách hàng bổ sung đầy đủ hợp đồng theo quy định hoặc đơn phương chấm dứt hợp đồng trước thời hạn.</p><p>Với quyết định riêng và tuyệt đối của mình, SOC có thể thay đổi hoặc sửa đổi Thỏa thuận này và mọi chính sách cũng như các điểm nhất trí đi kèm vào bất cứ lúc nào, những thay đổi hoặc sửa đổi đó sẽ có hiệu lực ngay lập tức sau khi được đăng lên website này.  Việc Quý khách sử dụng website này hay các Dịch vụ sau khi những thay đổi hoặc sửa đổi trên đã được thực hiện đồng nghĩa với việc Quý khách chấp nhận Thỏa thuận này như được sửa đổi lần cuối.  Nếu Quý khách không đồng ý chịu sự ràng buộc bởi Thỏa thuận này như được sửa đổi lần cuối thì Quý khách có thể không tiếp tục sử dụng website này hay các Dịch vụ trên website này.</p><p><b>Điều 2: Giải thích từ ngữ</b></p><p><span style=\"font-size: 1rem;\">\"SOC\", \"Chúng tôi\", \"Bên B\": Là Công ty Cổ Phần SOC</span><br></p><p><span style=\"font-size: 1rem;\">\"Bạn\", \"Quý khách\", \"Khách hàng\", \"Người sử dụng\", \"Bên A\": Là người sử dụng website này hoặc là người mua và sử dụng các dịch vụ trên website này.</span></p><p><b>Điều 3: Quyền và trách nhiệm của khách hàng (Bên A)</b></p><p>Nếu Quý khách (Bên A) đăng ký dịch vụ Thuê chỗ đặt server (Co-Location) hoặc Thuê Server Riêng (Dedicated) hoặc Thuê Server Ảo (VPS):</p><p><span style=\"font-size: 1rem;\">- Bên A có trách nhiệm vận hành quản lý, sao lưu, phục hồi dữ liệu server, bảo trì, xử lý sự cố phần cứng. Chịu trách nhiệm quản lý nội dung thông tin trên máy chủ, đảm bảo các thông tin này không trái với những quy định của pháp luật.</span></p><p><span style=\"font-size: 1rem;\">- Tuân thủ và chịu trách nhiệm theo các quy định của Nhà nước và quốc tế về sử dụng dịch vụ Internet, quyền sở hữu công nghiệp, bản quyền hệ điều hành, phần mềm cài đặt trên máy chủ (nếu có), bí mật quốc gia, an ninh, văn hoá.</span></p><p>Nếu Quý khách (Bên A) đăng ký dịch vụ Lưu Trữ Website (Web Hosting):</p><p>- Bên A có trách nhiệm bảo mật quyền đăng nhập vào hệ thống và thông tin ra vào dịch vụ đăng ký, chịu trách nhiệm trước pháp luật khi có các hành vi vi phạm pháp luật từ việc sử dụng dịch vụ này. </p><p>Nếu Quý khách (Bên A) đăng ký Tên miền (Domain):</p><p>- Bên A có trách nhiệm kiểm tra và chắc chắn rằng tên miền đã được đăng ký hoặc gia hạn trên INTERNIC (đối với domain quốc tế) hoặc VNNIC (đối với domain .VN) sau khi đăng ký hoặc gia hạn tên miền.</p><p>- Có trách nhiệm nộp bản khai đăng ký tên miền .VN cho Bên B theo quy định của VNNIC, tuân thủ các Quy định về quản lý và sử dụng tài nguyên Internet của Bộ Thông Tin và Truyền Thông nếu Bên A có đăng ký tên miền .VN. </p><p>- Có trách nhiệm khai báo thông tin tên miền quốc tế trên trang web <a href=\"http://www.thongbaotenmien.vn\" target=\"_blank\">www.thongbaotenmien.vn</a> nếu Bên A có đăng ký tên miền quốc tế. </p><p>- Bên A có trách nhiệm bảo mật quyền đăng nhập vào hệ thống quản trị tên miền và chịu mọi trách nhiệm trước pháp luật khi có các hành vi vi phạm pháp luật từ việc sử dụng tên miền.</p><p>Nếu Quý khách (Bên A) đăng ký dịch vụ Locking Domain .VN:</p><p>- Bên A chuyển toàn bộ tên miền đăng ký dịch vụ này về Bên B quản lý và thay đổi Name server của các tên miền này sang sử dụng Name server do Bên B cung cấp.</p><p>- Bên A không được chuyển tên miền sang nhà đăng ký khác khi chưa hết hạn hợp đồng.</p><p>- Cung cấp thông tin người có quyền quyết định đối với các tên miền này theo Phụ lục 1 đính kèm hợp đồng này theo thông tin trên bản khai tên miền.</p><p><b>Điều 4: Quyền và trách nhiệm của SOC (Bên B)</b></p><p>Nếu Quý khách (Bên A) đăng ký dịch vụ Thuê chỗ đặt server (Co-Location):</p><p>- Bên B không chịu bất cứ trách nhiệm pháp lý hoặc bồi thường thiệt hại nào về việc mất dữ liệu trên server. </p><p>- Bên B không chịu trách nhiệm về bản quyền hệ điều hành và phần mềm trái phép mà Bên A sử dụng trên server.</p><p>- Khi Bên A có văn bản chính thức chấm dứt Hợp đồng và hoàn thành việc chi trả các khoản phí phát sinh, Bên B sẽ gửi trả cho Bên A máy chủ hoặc các thiết bị của Bên A đặt tại phòng máy của Bên B.</p><p>Nếu Quý khách (Bên A) đăng ký dịch vụ Thuê Server Riêng (Dedicated) hoặc Thuê Server Ảo (VPS):</p><p>- Bên B sẽ thay thế phần cứng miễn phí trong suốt thời gian sử dụng nếu phần cứng Bên B có lỗi trong vòng 72h.</p><p>- Bên B không chịu bất cứ trách nhiệm pháp lý hoặc bồi thường thiệt hại nào về việc mất dữ liệu trên server. </p><p>- Bên B không chịu trách nhiệm về bản quyền hệ điều hành và phần mềm trái phép mà Bên A sử dụng trên server.</p><p>Nếu Quý khách (Bên A) đăng ký dịch vụ Lưu Trữ Website (Web Hosting):</p><p>- Bên B cung cấp cho Bên A các thông tin tài khoản (username, password) của web hosting sau khi Bên A đăng ký.</p><p>- Bên B không chịu bất cứ trách nhiệm pháp lý hoặc bồi thường thiệt hại nào về việc mất dữ liệu trên web hosting.</p><p>Nếu Quý khách (Bên A) đăng ký Tên miền (Domain):</p><p>- Bên B cung cấp cho Bên A các thông tin tài khoản (username, password) của tên miền sau khi Bên A đăng ký.</p><p>- Tất cả các vấn đề tranh chấp liên quan tên miền Việt Nam của hợp đồng này, Bên B sẽ xử lý căn cứ theo quy định của Trung tâm Internet Việt Nam (VNNIC). Tất cả các vấn đề tranh chấp liên quan tên miền quốc tế của hợp đồng này, Bên B sẽ xử lý căn cứ theo quy định của tổ chức quản lý tên miền cấp cao nhất (ICANN). Bên B không chịu bất kỳ trách nhiệm nào liên quan.</p><p>- Trong thời gian ký hợp đồng và tiến hành thanh toán nếu tên miền bị chủ thể khác đăng ký thì Bên B hoàn toàn không chịu trách nhiệm. Trường hợp tên miền đã bị đăng ký bởi một chủ sở hữu khác không phải Bên A, hoặc không gia hạn được,  Bên B có trách nhiệm hoàn lại chi phí đăng ký hoặc phí gia hạn tên miền cho Bên A.</p><p>Nếu Quý khách (Bên A) đăng ký dịch vụ Locking Domain .VN:</p><p>- Bên B sẽ đăng ký dịch vụ này với VNNIC. Tên miền Bên A sau khi đăng ký bảo vệ, trạng thái sẽ được thể hiện khi whois là:</p><p>     Status:</p><p>          clientDeleteProhibited, </p><p>          clientTransferProhibited, </p><p>          clientUpdateProhibited, </p><p>          serverDeleteProhibited, </p><p>          serverTransferProhibited, </p><p>          serverUpdateProhibited</p><p>- Bên B cung cấp giấy chứng nhận tên miền và hóa đơn cho Bên A theo đúng nội dung đã thỏa thuận tại Điều 1 của hợp đồng này.</p><p><b>Điều 5: Quy định về việc sử dụng tên miền</b></p><p>5.1 Tên miền là tài nguyên đặc biệt, được cấp cho chủ thể nào đăng ký trước. SOC cung cấp dịch vụ đăng ký tên miền cho khách hàng trong phạm vi tên miền chưa có chủ thể khác đăng ký trong thời gian đăng ký và hoàn thành việc đăng ký tên miền, được sự chấp thuận cấp phép sử dụng của cơ quan quản lý tên miền.</p><p>5.2 Trường hợp tên miền không đăng ký được do thuộc sở hữu của cá nhân, đơn vị khác, SOC sẽ hoàn lại 100% phí đăng ký tên miền cho Quý khách.</p><p>5.3 Quý khách thừa nhận và đồng ý rằng dịch vụ đăng ký tên miền không được hoàn lại phí khi đã thực hiện việc đăng ký, đã gia hạn hoặc Quý khách đơn phương chấm dứt việc sử dụng dịch vụ.</p><p>5.4 Khi đã hoàn tất đăng ký, Quý khách không thể chỉnh: (a) sửa tên của tên miền, (b) tên của chủ thể đối với tên miền .VN trừ những trường hợp cụ thể do VNNIC quy định.</p><p>5.5 Tên miền hết thời hạn sử dụng mà không đóng phí duy trì sẽ bị hủy và được cấp phát cho các chủ thể khác. SOC không còn quyền quản lý và trách nhiệm với chủ thể của tên miền không tiếp tục gia hạn sử dụng.</p><p>5.6 Quý khách phải chủ động theo dõi thời hạn tên miền và thực hiện việc gia hạn trước khi tên miền hết hạn. SOC không chịu trách nhiệm về việc ngưng trệ hoặc mất tên miền vì lý do chủ thể không thanh toán phí gia hạn hoặc thanh toán phí chậm trễ.</p><p>5.7 Quý khách là chủ thể sở hữu tên miền phải tự quản lý và tự chịu trách nhiệm về việc sử dụng tên miền của mình. SOC không chịu mọi trách nhiệm khi Quý khách sử dụng tên miền tham gia vào các hoạt động vi phạm pháp luật.</p><p>5.8 Tất cả các vấn đề tranh chấp liên quan tên miền .VN, chúng tôi sẽ xử lý căn cứ theo quy định của Trung Tâm Internet Việt Nam (VNNIC). Tất cả các vấn đề tranh chấp liên quan tên miền quốc tế , chúng tôi sẽ xử lý căn cứ theo quy định của tổ chức quản lý tên miền cấp cao nhất (ICANN)</p><p><b>Điều 6: Quy định về việc sử dụng web hosting, server</b></p><p>6.1. Chúng tôi (SOC) không chịu trách nhiệm và không bảo đảm về tính chính xác của những thông tin từ bất kỳ ai gửi đến server và cũng không chịu bất cứ trách nhiệm pháp lý hoặc bồi thường thiệt hại nào về việc mất mát hay hư hỏng đối với dữ liệu được lưu trữ trên server.</p><p><span style=\"font-size: 1rem;\">6.2. Người sử dụng có trách nhiệm thực hiện việc duy trì và bảo quản dữ liệu trên server.</span><span style=\"font-size: 1rem;\">   </span></p><p>6.3. Người sử dụng phải tự chịu trách nhiệm và đảm bảo với chúng tôi trong việc sử dụng Website hay Server của mình vào những mục đích hợp pháp. Đặc biệt trong những trường hợp sau:</p><p>      6.3.1. Không dùng máy chủ hay dịch vụ lưu trữ vào bất kỳ mục đích/hình thức nào vi phạm pháp luật Việt Nam và Quốc tế, đặc biệt về vấn đề bản quyền hệ điều hành, phần mềm, ca khúc... Đồng thời có trách nhiệm kiểm soát và ngăn cấm người khác làm điều đó trên máy chủ  hay dịch vụ lưu trữ của mình.</p><p>      6.3.2. Người sử dụng không được gửi, tạo liên kết hoặc trung chuyển cho:</p><p>               a. Bất kỳ loại dữ liệu nào mang tính bất hợp pháp, đe dọa, lừa dối, thù hằn, xuyên tạc, nói xấu, tục tĩu, khiêu dâm, xúc phạm, thông tin trộm cắp... hay các hình thức bị ngăn cấm khác dưới bất kỳ cách thức nào.</p><p>               b. Bất kỳ loại dữ liệu nào mà cấu thành hoặc khuyến khích các hình thức phạm tội; hoặc các dữ liệu mang tính vi phạm luật sáng chế, nhãn hiệu, quyền thiết kế, bản quyền hay bất kỳ quyền sở hữu trí tuệ hoặc các quyền hạn của bất kỳ cá nhân nào.</p><p>      6.3.3. Người sử dụng không được gửi các hình thức bulk email, spam email mang mục đích phá hoại từ server hay mạng của chúng tôi và không được khuyến khích một site nào đó được đặt trên server sử dụng bulk email, spam mail.</p><p>      6.3.4. Người sử dụng không được sử dụng các chương trình có khả năng làm tắc nghẽn máy chủ, gây cạn kiệt tài nguyên, làm quá tải bộ vi xử lý và bộ nhớ của máy chủ. Hoặc sử dụng tài nguyên vượt quá mức tài nguyên cho phép của gói dịch vụ, do chúng tôi quy định.</p><p>6.4. Người sử dụng giữ một cách an toàn các thông tin nhận biết, mật khẩu hay những thông tin mật khác liên quan đến tài khoản của bạn và lập tức thông báo cho chúng tôi khi bạn phát hiện các hình thức truy cập trái phép bằng tài khoản của bạn hoặc các sơ hở về bảo mật, bao gồm việc mất mát, đánh cắp hoặc để lộ các thông tin về mật khẩu và các thông tin bảo mật khác.</p><p>6.5. Người sử dụng tuân thủ các thủ tục mà chúng tôi đưa ra và sẽ không được dùng hosting và server vào những mục đích có thể gây ảnh hưởng đến các khách hàng khác của chúng tôi.<span style=\"font-size: 1rem;\">   </span></p><p>6.6. Bất kỳ việc truy cập đến những mạng khác được liên kết với mạng chúng tôi đều phải tuân theo các luật tương ứng của các mạng đó.<span style=\"font-size: 1rem;\">   </span></p><p>6.7. Trong khi chúng tôi dùng các biện pháp có thể và nỗ lực nhằm bảo đảm sự toàn vẹn dữ liệu và an toàn cho server, chúng tôi không đảm bảo trong trường hợp server bị phá hoại từ những người dùng bất hợp pháp hay các hacker cũng như lỗi phần cứng do nhà sản xuất và cũng không chịu trách nhiệm đối với các trường hợp mất mát dữ liệu.</p><p><b>Điều 7: Quy định về bảo mật thông tin</b></p><p>Quy định về bảo mật thông tin: <a href=\"https://socjsc.com/vi/article/privacy-policy-1/\">Click để xem tại đây</a>.</p>','<p><b>Article 1: Overview</b></p><p>Negotiate terms of this joint service (the \"Agreement\") is entered into by the parties to the SOC Co., Jsc. (abbreviated as SOC) and customers, effective from the date you use the website present. This agreement specifies the terms and conditions on the website you use, as well as products and services are bought or used through this website, and complement (not substitute for) anything Terms and conditions are applied to specific services.</p><p>Whether you are simply browsing or using this website or purchase of services, the use of this website and the 